(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["so"] = {"ui":{"skip":"U gudub nuxurka","back":"← Ku laabo AI-gile","lang.button":"Luuqad: {name}","lang.dialog":"Dooro luqad","lang.search":"Raadi luqadaha","lang.none":"Luqad waafaqsan ma jirto","lang.notYet":"{name} wali lama turjumin","theme.aria":"Beddel mawduuca: iftiin, mugdi ama madow","theme.toLight":"U beddel mawduuca iftiinka","theme.toDark":"U beddel mawduuca mugdiga","theme.toBlack":"U beddel mawduuca madow (madow dhab ah, ku fiican shaashadaha OLED)","words.underline":"Hoosta ka xarriiq erayadan bogga ku jira","words.underlineHelp":"Dul mar ama taabo eray dhibcaysan si aad u aragto macnihiisa.","words.col.todo":"Kaararka hadda la doortay: kooxdu waxay ku bilaabi doontaa kuwan marka xigta.","words.col.doing":"AI ayaa hadda ka shaqaynaya kaarkan.","words.col.review":"AI mid ah ayaa shaqada dhammeeyay; mid kale ayaa hubiya intaanay kuu soo gaadhin.","words.col.verify":"Adiga ayaa laga sugayaa: tijaabi oo ii sheeg haddii ay shaqayso.","words.col.team":"Qoraalladaada ama jawaabahaaga, oo sugaya in kooxdu qaado.","words.col.done":"La dhammeeyay oo la aqbalay.","index.title":"AI-gile: kooxdaada AI ee horumarinta, hal looxa","index.description":"AI-gile waa looxa kanban ee kooxaha barnaamijinta AI. Way shaqeeyaan inta aad hurdo; adiga waxaa kuu yimaada hal xirmo gaaban oo wax aad go'aamiso, tijaabiso oo aqbasho.","hero.logoAlt":"Astaanta looxa AI-gile","hero.h1.html":"Kooxdaada AI ee horumarinta, hal&nbsp;looxa.","hero.alpha":"🐣 Pre-alpha xiran","hero.alphaTitle":"Waa hore oo aan dhammaystirnayn: mahadsanid tijaabintaada!","hero.lede":"Way dhisaan inta aad hurdo. Waxaad toosaysaa hal xirmo gaaban: dhowr su'aalood, dhowr wax oo la tijaabiyo, hal ama laba dheeman oo guduudan-buluug ah. Guji, aqbal, oo ku laabo qaxwahaaga.","dl.windows":"Abka Windows","dl.browser":"Ku fur biraawsarka","dl.messenger":"📱 Messenger taleefankaaga","dl.soon":"Dhowaan","dl.notify":"🔔 I sheeg marka la furo","dl.notifySmall":"Alpha ama beta","hero.secondary":"Agile, laakiin kooxdu waligeed uma baahna qaxwada kulanka gaaban. (Kulamada gaagaabyada ah way sameeyaan si kastaba.)","pitch.h2":"AI-gile ereyo intaad rabto ku jira","pitch.lede":"Dooro dherer, hal eray ilaa 144. Dherer kasta waa sharaxaad u gaar ah, loo qoray cabbirkaas. Jiid sabuurka ama isticmaal fallaadhaha.","pitch.rangeLabel":"Dhererka ereyada","pitch.dice":"🎲 nooc kale","pitch.words.one":"{n} eray","pitch.words.other":"{n} eray","pitch.letters.one":"{n} xarfo","pitch.letters.other":"{n} xarfood","pitch.chars.one":"{n} xaraf","pitch.chars.other":"{n} xaraf","count.line.html.one":"{n} kaar ayaa hadda looxa ku jira","count.line.html.other":"{n} kaar ayaa hadda looxa ku jira","people.humans.html.one":"👥 {n} qof","people.humans.html.other":"👥 {n} qof","people.agents.html.one":"🤖 {n} wakiil","people.agents.html.other":"🤖 {n} wakiil","people.working.html.one":"⚡ {n} ayaa hadda shaqaynaya","people.working.html.other":"⚡ {n} ayaa hadda shaqaynaya","pre.title":"AI-gile: wax baa la dhisayaa","pre.description":"Halkan wax baa laga dhisayaa: loox ay kooxo AI ah ku dhisaan waxaad codsato, oo ay wax kugu baraan inta ay shaqeynayaan. Hadda waa pre-alpha xiran oo saaxiibo la wadaago.","pre.h1":"Halkan wax baa laga dhisayaa. 🤫","pre.line":"Loox ay kooxo AI ah ku dhisaan waxaad codsato, oo ay wax kugu baraan inta ay shaqeynayaan. Hadda waa pre-alpha xiran oo saaxiibo la wadaago.","pre.btn":"🔔 I sheeg marka la furo","pre.peek":"Muraayadda gadaasheeda: looxa dhabta ah, toos. Kaar kastaa waa xariiq midab leh.","pre.peekFake":"Muraayadda gadaasheeda: sidaan buu u eg yahay loox shaqeynaya.","pre.night":"🌙 Waardiyaha habeenka ayaa mas'uul ah · 😴 aadanuhu wuu nasanayaa","features.aria":"Wuxuu sameeyo","f.pile.h":"Hal xirmo adiga kuu ah","f.pile.html":"<b>Adiga</b> wuxuu ururiyaa wax kasta oo ku sugaya, mashruuc kasta: su'aalo, wax la tijaabiyo, hawlo uu qof kaliya samayn karo. Safkaaga ayaa kuu sheegaya waxa xiga iyo inta uu qaadanayo.","f.sleep.h":"Kooxo shaqeeya inta aad hurdo","f.sleep.p":"Mashruuc kastaa wuxuu leeyahay hoggaamiye iyo koox wakiilo AI ah. Kaarka ka dhiib faallo, kooxdu way toostaa, shaqada way qabataa, oo waxay kuu soo celisaa tallaabooyin uu qof daallan raaci karo.","f.tester.h":"Tijaabiyaha AI ayaa marka hore hubiya","f.tester.p":"Intaan wax adiga kuu imaan, tijaabiyuhu wuxuu raacaa tallaabooyinka nuqul ka mid ah abka wuxuuna muujiyaa waxa uu arkay, isagoo leh sawir shaashad. Dhex mar kuwa gudbay oo ku aqbal hal gujin.","f.proof.h":"Caddayn, ma ahan ballanqaadyo","f.proof.p":"Gacan-ka-gacan kasta wuxuu muujiyaa waxa isbeddelay: faylasha, farqiga, sawirada shaashadda. Uma baahnid inaad fureyso abka kasta si aad u aragto in la dhammeeyay.","f.chat.h":"La sheekayso hoggaamiyayaashaada","f.chat.p":"Tiir u eg Discord: hal astaan mashruuc kasta, dheeman guduudan-buluug ah waxa adiga ku baahan. Hoggaamiye u dir fikrad; wuxuu u beddelaa kaararka iyo qorshe, iyo badhanka ✅ Bilow.","f.tidy.h":"Is nadiifiya","f.tidy.p":"Kaararka isku xiga way is-dhex galaan, cinwaannada qalafsan waa la saxaa, hubinta tokenka ayaa koodhka ilaaliya mid khafiif ah. Wax yar oo la beddelo, wax yar oo la fekero.","f.private.h":"Adigaa leh, kombiyuutarkaaga","f.private.li1":"Looxu wuxuu ku shaqeeyaa mashiinkaaga, wuxuuna ka jawaabaa adiga oo keliya.","f.private.li2":"Fariimaha gaarka ah ee dadka dhexdooda waa la sir-qarsoodiyey dhammaadka ilaa dhammaadka.","f.private.li3":"Akoon ma jiro, raadraac ma jiro, cookies ma jiraan.","f.lang.h":"Luqaddaada","f.lang.p":"In ka badan 120 luqadood, Holandays, Welsh iyo Jabaaniis ilaa budhcad-badeed, Yoda iyo Klingon, oo leh beddelid degdeg ah oo Ingiriisi ah ee ereyada xirfadda.","f.service.h":"Fikrad ilaa adeeg dhab ah","f.service.p":"Ma ku dhistay AI wax dadku hadda isticmaalaan? U calaamadee adeeg, sabuuraduna waxay kaa caawinaysaa inaad si fiican u maamusho: hubinta shaqeynta, bog xaaladeed oo dadweyne, shilal leh dib-u-eegis qoran, isbeddello u baahan Go, kaydad maalin kasta la hubiyo. Caawimadu waxay ku bartaa tallaabo kasta intaad socoto.","msgr.h2":"AI-gile Messenger: kooxdaadu jeebkaaga","msgr.p1":"La hadal kooxdaada AI adigoon furin boardka. La sheekayso hoggaamiyeyaasha mashruucaaga iyo saaxiibbadaa, oo arag tallaabooyinka tijaabada ee kaar oo ka jawaab, dhammaan taleefankaaga.","msgr.p2":"Si aad isugu xirto, iskaan garee QR code ku yaal boardkaaga. Markii ugu horreysay? Sheeko demo ah oo saaxiibtinimo leh ayaa ku tusaysa.","msgr.when":"Marka hore Android, kadib nooc web ah oo loogu talagalay taleefannada iyo iPhone.","msgr.who":"Hoggaamiyaha mashruucaaga","msgr.b1":"Hagaajinta habka mugdiga diyaar weeye. Ma rabtaa tallaabooyinka tijaabada?","msgr.b2":"Haa, fadlan!","msgr.b3":"1. Fur Settings. 2. Dooro Dark. Si sax ah ma u muuqataa?","tl.aria":"Jadwalka laga bilaabo wada hadalkii ugu horreeyay ilaa qorshaha","tl.h2":"Sheekadii ugu horreysay ilaa waxa xiga","tl.lede":"Taariikho iyo waqtiyo dhab ah, aagga waqtigaaga. Maanta ka dib waa qorshe, taariikho lama ballanqaadin.","tl.today":"Maanta","tl.planned":"la qorsheeyay","tl.doing":"socda","tl.cards.one":"{n} kaar","tl.cards.other":"{n} kaar","join.h2":"Ku soo biir","join.lede":"AI-gile waxaa dhisaya nin gadh leh oo qariib ah, qaba AuDHD, oo dhowr jeer la dagaalamay caafimaadka maskaxda, iyo wakiilo badan oo samir badan. Hadda waa gaar, alpha xiran oo asxaab ah. Ma rabtaa inaad tijaabiso marka la furo?","join.btn":"Muuji xiisaha","join.small":"Iimayl ayaan kuu qori doonaa, wax kale ma jiro","footer.tag":"AI-gile. Raadraac la'aan, cookies la'aan, qaxwo kulan la'aan.","footer.licence":"Shahaadada ganacsiga","footer.status":"Xaaladda","footer.privacy":"Waxa aan haynno","footer.thanks":"Wicitaanada waxaa suurtagaliyay ChilledChat","form.sending":"Waa la dirayaa…","form.failed":"Ma shaqayn: mar dambe isku day.","form.offline":"AI-gile lama gaari karin: mar dambe isku day.","form.keep":"Waxaan u isticmaalnaa oo keliya inaan kuugu jawaabno, kadibna waan tirtirnaa. Raadraac la'aan, cookies la'aan.","form.keepLink":"Waxa aan haynno","interest.title":"AI-gile: i sheeg marka alpha la furo","interest.description":"Iimaylkaaga reeb si aad u ogaato marka alpha ama beta xiran ee AI-gile la furo.","interest.h1":"🔔 I sheeg marka la furo","interest.lede":"AI-gile waa pre-alpha xiran. Iimaylkaaga reeb, mar keliya ayaan kuu qori doonnaa marka meel adiga kuu jirto.","interest.email":"Iimaylkaaga","interest.which":"Tijaabo kee?","interest.alpha":"Alpha xiran: hore, qallafsan, isbeddello badan","interest.beta":"Beta: xasiloon, dambe","interest.both":"Mid kasta, kii hore yimaada","interest.submit":"Liiska igu dar","interest.thanks":"Mahadsanid! Liiska waad ku jirtaa.","licence.title":"AI-gile: shahaadada ganacsiga","licence.description":"Ma ku isticmaashaa AI-gile ganacsigaaga? Codso shahaado ganacsi oo bilaash ah.","licence.h1":"📜 Shahaadada ganacsiga","licence.lede":"Ma ku isticmaashaa AI-gile shaqada? Noo sheeg yaad tahay iyo waxaad qabato. Haddii wax wanaagsan sameeyo, shahaadadu waa bilaash.","licence.company":"Shirkadda","licence.website":"Boggaga","licence.what":"Waxaad qabato","licence.how":"Sida ay adduunka ugu caawiso","licence.email":"Iimaylka","licence.submit":"Codso","licence.thanks":"Mahadsanid! Iimayl ayaan kaaga jawaabi doonnaa.","status.title":"Xaaladda AI-gile","status.h1":"Xaaladda AI-gile","status.quiet":"Wax walba way degan yihiin","status.intro":"AI-gile ma shaqaynayaa hadda? Boggan wuxuu 5-tii daqiiqoba mar hubiyaa website-ka, wadaagista looxyada, wicitaannada iyo soo dejinta.","status.up":"Wuu shaqaynayaa (wuxuu ku jawaabay {ms} ms)","status.slow":"Kama jawaabin hubintii u dambaysay, mar kale ayaan isku dayayaa","status.down":"Wuu xiran yahay: kama jawaabin labadii hubin ee u dambeeyay","status.svc.web":"Website-ka","status.svc.web.offers":"Boggan: waxa uu AI-gile yahay, iyo foomka xiisaha","status.svc.boards":"Wadaagista looxyada","status.svc.boards.offers":"Looxyo dadweyne, fariimo saaxiibbada dhexdooda ah iyo casuumado","status.svc.calls":"Wicitaannada","status.svc.calls.offers":"Cod, muuqaal iyo wadaagista shaashadda gudaha AI-gile","status.svc.download":"Soo dejinta","status.svc.download.offers":"Rakibaha Windows iyo xiriirinnada casuumadda","status.checking":"Waa la hubinayaa…","status.offline":"Adeegga xaaladda hadda lama gaari karo (mar kale ayaan isku dayayaa)","status.updated":"la cusboonaysiiyay {ago}","status.justNow":"hadda dhawaan","status.min":"{n} daqiiqo ka hor","status.hours":"{n} saac ka hor","status.days":"{n} maalmood ka hor","privacy.title":"AI-gile: waxa aan haynno","privacy.h1":"Waxa aan haynno","privacy.lede":"Si kooban: kaliya waxaad noo soo dirto, mana aha muddo dheer.","privacy.only":"Kaliya waxaad noo soo dirto: waxaad ku qorto foom, sida iimaylkaaga. Wax kale oo adiga kugu saabsan ma jiraan.","privacy.sealed":"Waa la shaabadeeyaa si server-kayagu aanu u akhrin karin: biraawsarkaaga gudahiisa ka hor intaanu bixin (biraawsar duug ah, isla marka uu yimaado). Kaliya looxayaga ayaa furi kara.","privacy.server":"Server-ka waa laga tirtiraa isla marka uu gaaro looxayaga. Wax kasta oo halkaas ku haray 30 maalmood kadib si kastaba waa la tirtiraa.","privacy.board":"Waxaan ku haynaa looxayaga oo keliya ilaa aan kaaga jawaabno, kadibna halkaasna waan ka tirtirnaa.","privacy.none":"Raadraac la'aan, cookies la'aan, falanqayn la'aan.","privacy.local":"Luqaddaada iyo doorashadaada iftiinka ama mugdiga waxay ku jiraan biraawsarkaaga. Weligood nalooma soo diro.","privacy.ask":"Ma rabtaa in hore loo tirtiro? Ka jawaab iimaylkayaga oo noo sheeg.","live.h2":"Daawo markii la dhisayo, tooska","live.caption":"Kaarkasta waa qarsoon yahay: waxaad aragtaa qaabka shaqada, ma aha erayada.","live.watching.one":"tooska: {n} ayaa daawanaya","live.watching.other":"tooska: {n} ayaa daawanaya","live.last.now":"Kaarkii ugu dambeeyay waa la dhaqaajiyay hadda","live.last.min.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} daqiiqo ka hor","live.last.min.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} daqiiqo ka hor","live.last.hour.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} saac ka hor","live.last.hour.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} saacadood ka hor","live.last.day.one":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} maalin ka hor","live.last.day.other":"Kaarkii ugu dambeeyay waa la dhaqaajiyay {n} maalmood ka hor","live.offline":"Looxa tooska ah wuxuu qaadanayaa nasasho yar. Dhawaan dib u soo eeg.","live.cols":"Backlog|Waxa la sameeyo|Socda|Kooxdu way eegaysaa|Adiga oo test samaynaya|Kooxda|La dhammeeyay"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotyo.","Wakiilnimo."]},{"n":2,"texts":["Kanban robot.","Wakiilo nidaamsan.","Fikrado dhisan."]},{"n":3,"texts":["Kanban u ah robotyada.","Fikrad, dhis, aqbal.","Kanban wakiilo bilaash."]},{"n":5,"texts":["Looxa kanban oo wakiilo maamulaan.","Adigu qor kaararka. Wakiilladu dhis.","Bilaash, gudaha, tijaabo, qosol yar."]},{"n":8,"texts":["Looxa kanban oo bilaash ah halka wakiilo AI shaqeeyaan.","Qor fikrad. Wakiilladu way dhisaan. Adigu aqbal.","Agile hal qof iyo robotyo badan oo samir badan."]},{"n":13,"texts":["Looxa kanban ee kombiyuutarkaaga ku jira halka wakiilo AI ay kaararka qaataan oo ay ku shaqeeyaan.","Qor fikrad. Koox wakiilo ah ayaa dhisa. Tijaabiye ayaa hubiya. Adigu waxaad dhahdaa haa.","Bilaash, akoon la'aan, raadraac la'aan: looxa, robotyo yar, iyo adiga oo xukumaya."]},{"n":21,"texts":["AI-gile waa looxa kanban oo lagu la shaqeeyo wakiilo AI ah oo barnaamijiya. Iyagu kaararka way qaataan; adiguna waad tijaabisaa oo aqbashaa.","Mashruuc kastaa wuxuu helaa hoggaamiye iyo koox wakiilo AI ah. Kaar kasta faallo ka qor, kooxduna way shaqo bilaabaysaa.","Looxa hawlaha shaqsiyeed oo bilaash ah oo kombiyuutarkaaga ku shaqeeya. Shaqaaluhu waa robotyo. Kan dhihi kara haa waa adiga."]},{"n":34,"texts":["Fikradaha looxa ayaad saartaa. Koox wakiilo AI ah ayaa u beddesha qaybo shaqeeya, way tijaabisaa, waxayna kuu soo celisaa tallaabooyin lagu tijaabiyo. Wax lama yiraahdo waa dhammaaday ilaa aad dhahdo.","AI-gile waa looxa kanban oo guri lagu sameeyay, kaas oo Rich ku dhisay caawimo badan oo ka timid wakiilada uu hadda xukumo. Waa bilaash, kombiyuutarkaaga ayuu ku shaqeeyaa, waxaana lala wadaagaa asxaabta, lama iibiyo.","Ka fikir looxa kanban oo caadi ah, oo leh tiirar laga bilaabo Backlog ilaa La dhammeeyay, marka laga reebo in kaararka qaataan wakiilo AI. Waxay sheegaan horumarka, waxay weydiiyaan marka ay hakadaan, had iyo jeer waxayna sugaan oggolaanshahaaga."]},{"n":55,"texts":["AI-gile waa looxa kanban oo kooxdu ka kooban tahay wakiilo AI. Mashruuc kastaa wuxuu leeyahay hoggaamiye qorsheeya shaqada iyo caawiyayaal dhisa. Marka sifo diyaar tahay, tijaabiye AI ah ayaa tijaabiya oo sawir shaashad qaata, ka dibna waxay ku dhacdaa xirmadaada. Aqbal, ama faallo qor, waana dib u sameeyaan.","Wuxuu ku bilaabmay hab qof keliya uu ku raaco fadhiyo badan oo barnaamijin AI ah isku mar, wuuna kobcay oo noqday looxa dhab ah. Wuxuu ku shaqeeyaa mashiinkaaga, akoon uma baahna, raadraac ma laha. Waa bilaash asxaabta iyo kuwa xiisaynaya. Sidoo kale ma dhammaystirna, sidaa darteed filo geesyo qallafsan iyo layaab mararka qaarkood.","Halkan waa nooca daacadda ah. Adigu weli waa inaad fikrado yeelataa, weliba waa inaad hubisaa natiijooyinka. AI-gile wuxuu qabtaa wax kasta oo u dhexeeya: kaararka ayuu u dhigaa nidaam, wuxuu kiciyaa wakiilka saxda ah marka aad faallo qorto, wuxuu tusaa si sax ah waxa isbeddelay, wuxuuna dhammaantood ku soo ururiyaa hal xirmo gaaban adiga kuu ah."]},{"n":89,"texts":["AI-gile waa looxa kanban oo bilaash ah oo aad ku wadato kombiyuutarkaaga. Halkii dad, mashruuc kastaa wuxuu leeyahay koox wakiilo AI ah: hoggaamiye u beddela fikradahaaga kaararka iyo qorshe, iyo caawiyayaal kaararka qaata marka la horumariyo. Marka wax la dhiso, tijaabiye AI ah ayaa raaca tallaabooyinka tijaabada oo kuu muujiya waxa uu arkay. Kadib wuxuu ku sugaa hal xirmo la yiraahdo Adiga. Waad aqbashaa, ama faallo ayaad qortaa kooxduna mar kale ayay isku dayaan. Wax kuma gaaraan La dhammeeyay adiga la'aantaa.","Dhowr wax oo laga yaabo inaadan filayn. Ilaaliyaha habeenka ayaa buuxiya tiirka Waxa la sameeyo inta aad hurdo, isagoo dooranaya kaararka aan jawaab kaa rabin. Tiriyaha tokenka ayaa muujiya intii wakiilladu isticmaaleen maanta iyo toddobaadkan, Habka Tokenka La'aan ayaana u sheegaya inay joojiyaan isticmaalka. Waad la fariisan kartaa asxaabta, fariimaha gaarka ahna waa la sir-qarsoodiyey dhammaadka ilaa dhammaadka. Looxu wuxuu ku hadlaa ilaa 120 luqadood, oo ay ku jiraan Holandays, Flemish, budhcad-badeed iyo Klingon. Midkoodna sentimo ma ku kacayo, cidna isku dayin inay kuu iibiso.","AI-gile waa mashruuc yar oo shakhsi ah, ma aha shirkad. Rich wuxuu rabay inuu ilaaliyo dhowr mashruuc oo barnaamijin AI ah isagoo aan furin abka kasta si uu u hubiyo, sidaa darteed isaga iyo wakiilladu waxay dhiseen looxa, kadibna looxa ayay ku dhiseen inta kale ee naftiisa. Waa pre-alpha xiran, taasoo la macno ah inuu shaqeeyo, inta badan, koox yar oo asxaab ah. Bog qiimo ma leh, wargeys ma leh, qorshe kobac ma leh. Haddii ay kuu ekaato mid faa'iido leh, waad codsan kartaa inaad tijaabiso marka wax yar ka badan la furo."]},{"n":144,"texts":["AI-gile waa looxa kanban oo hal qof iyo wakiilo AI badan u ah. Wuxuu ku shaqeeyaa kombiyuutarkaaga wuxuuna yahay bilaash dhan. Waxaad ku darsataa mashruucyo, mid kastana wuxuu helaa hoggaamiye iyo koox yar. Waad la sheekaysataa hoggaamiyaha, in yar sida Discord, waxaadna sifaysaa fikrad; hoggaamiyuhu wuxuu u beddelaa kaararka iyo qorshe, kadibna wuu sugaa inta aad gujinayso Bilow. Kooxdu waxay kaararka u gudubtaa sida mudnaanta u ahaato, iyadoo isticmaalaysa xariiq amar fudud oo loo sameeyay moodooyinka luqadda. Intaan wax kuu soo noqon, tijaabiye AI ah ayaa raaca tallaabooyinka nuqul ka mid ah abka oo ku lifaaqa sawir shaashad. Shaqada dhammaatay waxay ku dhacdaa xirmadaada iyada oo leh faylasha la beddelay iyo farqiga. Waad aqbashaa, ama faallo ayaad ka tagtaa kooxduna way toostaa oo mar kale isku daydaa. Kaar u gudbin La dhammeeyay waxaad samayn kartaa adiga oo keliya.","Maalin AI-gile la qabo, qiyaas ahaan. Fiidkii waxaad ka tagtaa dhowr faallo: badhankan meel qaldan buu yahay, liiskaas waa in la kala saaro, ma yeelan karnaa habka mugdiga. Waad seexataa. Wakiilladu faallooyinka way akhriyaan, isbeddellada way samaystaan, way tijaabiyaan oo way kuu soo celiyaan. Haddii Waxa la sameeyo engegto, ilaaliyaha habeenka ayaa ka buuxiya backlog-ga kaararka aan jawaab kaa rabin. Subaxdii waxaa jirta hal xirmo gaaban: dhowr su'aalood iyo dhowr wax la tijaabiyo, mid kastana wuxuu leeyahay tallaabooyin uu qof hurdo ku jiro raaci karo iyo sawir muujinaya inuu shaqeeyo. Waad dhex marisaa, waxa wanaagsan aqbashaa, inta kalena celisaa. Tiriyaha tokenka ayaa muujiya waxa dhammaantood isticmaaleen, Habka Tokenka La'aan-na wuxuu u diyaar yahay toddobaadyada dhaqaalaha yar. Kadib waxaad cunta quraac, taas oo wakiilladu weli kaa caawin kari waayeen.","Marka hore, waxa AI-gile ahayn maaha. Ma aha startup, lama iibiyo, cidna ma ururiso xogtaada. Waa looxa bilaash ah oo kombiyuutarkaaga ku shaqeeya, akoon la'aan, raadraac la'aan iyo cookies la'aan. Waxa uu yahay: hal meel nadiif ah oo aad ku aragto mashruucyada barnaamijinta AI dhammaan isku mar, iyadoo koox wakiilo ah ay samaynayaan kaararka adiguna aad go'aamineyso. Wuxuu isku dhex yeelaa kaararka isku xiga, wuxuu saxaa cinwaannada qalafsan, wuxuuna fiiriyaa in koodhku khafiif ahaado. Wuxuu ku hadlaa ilaa 120 luqadood, laga bilaabo Holandays iyo Flemish ilaa budhcad-badeed iyo Klingon. Asxaabtu waa isu qori karaan gaar ahaan oo sir-qarsoodi ah. Waxaa dhisay Rich iyo tiro badan oo wakiilo samir badan ah, inta badan isagoo isticmaalaya naftiisa. Waa pre-alpha xiran, sidaa darteed meelaha qaarkood waa qallafsan yahay. Haddii ay kuu ekaato wax xiiso leh, si wanaagsan weydiiso, laga yaabee inaad hore u gasho."]}],"quips":{"1":"Hal eray. Dhiirrasho. Laga yaabee xad-dhaaf.","3":"Seddex eray. Hadda ka daacad badan bogagga badeecadaha intooda badan.","8":"Siddeed eray. Wali way ka gaaban yihiin kulan gaaban.","21":"Dhererradu waa story points, dariiqa. Hubaal ayay yihiin.","55":"Shan iyo konton eray. Laba kaar ayaa la dhammeeyay intaad akhrinaysay.","144":"Tani waa tan dheer. 233 ma jirto. Wakiilladii way seexdeen."}},"timeline":{"first-idea.name":"Fikraddii ugu horreysay","first-idea.line":"Wada hadalkii ugu horreeyay, intaan koodh jirin.","first-board.name":"Looxii ugu horreeyay","first-board.line":"Loox raacaya dhismihiisa: kaararka, tiirarka, jiid oo dhig, mashruucyada.","team-roles.name":"Koox iyo doorar","team-roles.line":"Astaamaha wakiilada, qaabdhismeedyada kooxaha, meelaha iyo yaa maxay qabanaya.","install.name":"Rakibid iyo daabacaado","install.line":"Zip uu saaxiib rakibi karo, is-cusboonaysiin, kanaalo iyo dib u noqosho.","usage-saver.name":"Badbaadiyaha isticmaalka","usage-saver.line":"Cabbir waxa socodku ku kacaan, koodhka khafiif ka dhig, xadkaaga badbaadi.","friends.name":"Asxaab iyo wadaagid","friends.line":"Fariimo gaar ah, gudbiye qarsoon, casuumaado, doorar iyo mashruucyo la wadaago.","languages.name":"Luqadaha","languages.line":"Qoraal shaashad kasta faylka luqadda, Holandays iyo Flemish marka hore.","ai-tester.name":"Tijaabiyaha AI","ai-tester.line":"Tijaabiye ayaa marka hore hubiya gacan-ka-gacan kasta oo muujiya waxa uu arkay.","website.name":"Mareegta","website.line":"aigile.lol, hordhaca iyo jadwalkan.","streaming.name":"Sheeko iyo tooska","streaming.line":"Discord, Twitch, OBS, habka tooska, GIF-yo iyo emoji.","no-ai.name":"Nooca aan AI lahayn","no-ai.line":"Loox dadka aan AI la'aan koodhka qorin, iyo looxyo dadweyne.","night-watch.name":"Ilaaliyaha habeenka","night-watch.line":"Ilaaliye iyo Scrum Master ayaa kooxaha shaqada ku haya inta aad hurdo.","p-more.name":"Wax kale oo dhan","p-more.line":"Fikrado yar oo wali sugaya inay noqdaan kuwa xiga.","p-android.name":"Taleefan iyo Android","p-android.line":"Looxaaga ka gaar taleefanka, kadibna abka Android ee asalka ah.","p-release.name":"Alpha iyo wixii ka dambeeya","p-release.line":"Alpha xiran, bogga tooska ah, kadibna beta.","p-languages.name":"Luqado dheeraad ah","p-languages.line":"130 luqadood, iyo hab quusta luqadda oo loogu talagalay kuwa baranaya.","p-engines.name":"Mishiinno AI dheeraad ah","p-engines.line":"Wakiil kasta u dooro Claude, Codex, Gemini, Copilot ama Cursor.","p-pro.name":"Hab-dhaqan xirfadeed","p-pro.line":"Calaamado khatar, albaabada isku-darka, kaararka dhacdooyinka iyo ilaalin.","p-self.name":"Ku daryeelidda adiga","p-self.line":"Habka daalka, xusuusinta is-daryeelka iyo 4:20.","p-servers.name":"Serfarro iyo ballaarin","p-servers.line":"Dejinta serfarka guud, doorar iyo qorsheynta kobaca.","p-livestream.name":"Dheeraadka tooska","p-livestream.line":"Sheekada Twitch, emoji gaar ah iyo muuqaal tooska ah oo dadweyne."},"words":{"button":"📖 Ereyada xirfadda","h":"📖 Ereyada la sharraxay","intro":"Ereyada aad kula kulanto AI-gile, si fudud loo sharraxay: dhisidda, si ammaan ah wax uga beddelidda, ka dhigidda inay u shaqeyso dadka isticmaala, iyo ka shaqeynta koox ahaan oo AI la jirto.","search":"Raadi eray…","none":"Eray ku habboon ma jiro.","close":"Xir","count":{"one":"{count} eray","other":"{count} eray"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Dhisidda"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Beddelid ammaan ah"},{"id":"run","name":"🛎️ Maamulidda adeeg"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Fikrado iyo shaqo aan weli la qorshayn. Waxba halkaas looma shaqeeyo ilaa ay u dhaqaaqdo Waxa la sameeyo."},{"id":"sprint","g":"agile","word":"Sprint","text":"Muddo gaaban oo shaqo ah (inta badan hal ama laba usbuuc) oo leh kaarar la isku raacay in la dhammeeyo.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Hubin degdeg ah: waxa xubin kasta qabatay, waxa xiga ee ay samayn doonto, iyo waxa joojinaya.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Board leh tiirar (Waxa la sameeyo, Socda, La dhammeeyay) halkaas oo kaararku ka dhaqaaqaan bidix ilaa midig marka shaqadu socoto."},{"id":"wip","g":"agile","word":"WIP limit","text":"Shaqo socota: kaararka ugu badan ee tiirku qaadi karo, si kooxdu u dhammeyso wax kahor intaysan bilaabin kuwo dheeraad ah.","also":["WIP"]},{"id":"dod","g":"agile","word":"Qeexidda La dhammeeyay","text":"Liiska gaaban ee kooxda ee waxa “dhammaaday” macnaheedu yahay, sida la tijaabiyay oo la sharraxay, ka hor inta kaar laguu dhiibin. Mataanaheeda, Qeexidda Diyaar, waxay sheegtaa goorta kaar ku filan yahay in la bilaabo.","also":["Definition of Done","Qeexidda Diyaar","Definition of Ready"]},{"id":"retro","g":"agile","word":"Dib-eegis","text":"Dib u eegis sida ay kooxdu u shaqeyso, si loogu heshiiyo hal shay oo si fiican loo sameeyo. AI-gile, dib-eegis waxay soo jeedisaa isbeddel habka shaqada kooxda, adiguna waxaad dhahdaa Hore u soco ama Wali ma aha.","also":["retro","retrospective","dib-eegisyo"]},{"id":"swarm","g":"agile","word":"Koox wada shaqeysa","text":"Gacan walba shaqada: koox kasta waxay dhigtaa shaqo kale si ay u caawiso hal mashruuc oo degdeg ah ilaa la xalliyo. Mashaariicda kale way sugaan inta lagu jiro.","also":["swarm","swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Qofka shaqada socodsiiya: arka kaarrada xayiran, dhiirrigeliya kooxaha oo ku xasuusiya waxa sugaya. AI-gile, Lead Scrum Master ayaa tan ka sameeya mashruuc kasta.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Folderka mashruuca ee koodhka iyo taariikhdiisa oo dhan ee commits-ka, inta badan sidoo kale lagu hayo GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Xariiq shaqo oo gaar ah koodhka ku jira, si isbeddello loo sameeyo iyada oo aan la taaban nooca ugu weyn.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Sawir la keydiyay oo koodhka ah, oo leh qoraal gaaban oo ku saabsan waxa isbeddelay. Had iyo jeer waad ku laaban kartaa mid.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"U dirista sawirrada la keydiyay (commits) kombuyuutarkan una gaarsiinta GitHub, si loo kaydiyo loona wadaago."},{"id":"merge","g":"build","word":"Merge","text":"Dib ugu biirinta isbeddelada branch-ka nooca ugu weyn."},{"id":"pr","g":"build","word":"Pull request","text":"Codsiga in isbeddelada branch la hubiyo oo lagu daro nooca ugu weyn.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Nadiifinta koodhka iyada oo aan la beddelin waxa uu sameeyo: faylal yar yar, magacyo cad, soo noqnoqod yar."},{"id":"bug","g":"build","word":"Bug","text":"Wax aan sidii loogu talagalay u shaqaynayn.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Indho labaad: AI kale ayaa hubisa shaqada kaar kasta ka hor inta uusan kuu soo gaarin, si khaladaad yar ay u dhaafaan.","also":["dib-u-eegis asxaab","code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Isku dayga shaqo dhammaatay si loo hubiyo inay sameyso waxa la weydiistay, ka hor intaadan aqbalin.","also":["tests"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Soo gaabinta quality assurance, xaqiijinta tayada: hubinta otomaatigga ah ee socota ka hor inta aan wax toos u bixin. Marka QA uu casaan yahay, wax baa fashilmay, mana bixi karo ilaa la hagaajiyo.","also":["hubinta tayada","xaqiijinta tayada"]},{"id":"testpile","g":"test","word":"Xirmada tijaabada","text":"Kaarrada la dhammeeyay ee sugaya inaad tijaabiso, mid mid. Mid aqbal ama dib ugu celi qoraal, kan xigaana wuu soo baxayaa.","also":["xirmooyinka tijaabada"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Dejinta nooc cusub toos ah, tusaale server dadku ku isticmaalaan."},{"id":"release","g":"change","word":"Sii deyn","text":"Xirmo magac leh oo shaqo dhammaatay ah oo wada toos u baxda, oo leh qoraallo gaaban oo ku saabsan waxa isbeddelay. 🚀 Sii deynta waxay qoraallada ka qortaa kaarrada la dhammeeyay.","also":["sii deynta","release"]},{"id":"rollback","g":"change","word":"Dib u celin","text":"Ku noqoshada nooca ugu dambeeyay ee shaqeynayay marka mid cusub dhibaato keeno. AI-gile waxay ka samaysaa liis hubin ah oo leh tallaabooyinka laga noqonayo ee ku qoran isbeddel kasta.","also":["rollback","dib u celi","dib loo celiyay"]},{"id":"live","g":"change","word":"Toos","text":"Nooca dhabta ah ee dadku isticmaalaan, oo ka duwan nuqul wax lagu tijaabiyo. Horumarinta waxay sidoo kale u yaqaanaan production.","also":["live","production","wax-soo-saar"],"noTip":1},{"id":"change","g":"change","word":"Isbeddel","text":"Isbeddel la qorsheeyay oo lagu sameynayo wax dadku ku tiirsan yihiin, oo marka hore la qoray: maxay, sababta, khatarta, goorta iyo sida looga noqon karo. Ku bilow 🔀 Soo bandhig isbeddel.","also":["isbeddello","codsi isbeddel","codsiyo isbeddel"],"noTip":1},{"id":"risk","g":"change","word":"Khatar","text":"Wax khaldami kara, oo lagu qiimeeyay inta ay u badan tahay iyo inta ay xumaan lahayd. ⚠️ Khataro waxay ku hayaan hal liis, dhibcaha ugu sarreeya marka hore, mid kasta oo leh taariikh dib loogu eego.","also":["khataro","diiwaanka khatarta"]},{"id":"chgwin","g":"change","word":"Daaqad isbeddel","text":"Waqtiyada isbeddelladu toos u bixi karaan, sida fiid Talaado ah oo deggan. Daaqadda dibaddeeda kaar isbeddel lama dhammeyn karo, haddii aanay ahayn xaalad degdeg ah.","also":["daaqadaha isbeddelka","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Cod degdeg ah oo la bixiyo kahor inta isbeddel uusan toos u bixin: qof kasta oo ay tahay inuu oggolaado wuxuu yiraahdaa Go ama No go. Wuxuu socdaa oo keliya marka ay isku raacaan.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Oggolaansho","text":"Sugidda haa kahor inta shaqadu aanay bilaabmin. Kaar saaxiib soo gudbiyay, ama isbeddel, wuxuu ku sugayaa ✅ Oggolaanshaha ilaa aad oggolaato ama diido.","also":["oggolaanshaha","oggolow"]},{"id":"quiettime","g":"change","word":"Waqti aamusnaan","text":"Muddo, sida baahin toos ah, bandhig ama habeenka, oo aan waxba toos u bixin. Kooxuhu way sii shaqeeyaan oo tijaabiyaan, laakiin toos u bixiddu way sugtaa ilaa ay dhammaato. Meelo kale waxaa loo yaqaan change freeze.","also":["waqtiyada aamusnaanta","joojinta isbeddelka","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Adeeg","text":"Wax aad dhistay oo dadku ku tiirsan yihiin, sida website ama app, oo la daryeelo si uu u sii shaqeeyo. Calaamadee “Mashruucan waa adeeg” oo sheeg waxa uu bixiyo, cidda isticmaasha iyo cidda xilka haysa.","also":["adeegyo","service"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Hubinta shaqeynta","text":"Hubin otomaatig ah, dhowr daqiiqo kasta, in adeeggaagu weli jawaabayo. Haddii ay dhowr jeer oo xiriir ah fashilanto, AI-gile waxay iskeed u furtaa kaar shil.","also":["uptime","hubinta uptime"]},{"id":"statuspage","g":"run","word":"Bogga xaaladda","text":"Bog dadweyne oo muujinaya in adeeg shaqeynayo iyo in kale (cagaar, oranji ama casaan) oo leh warkii ugu dambeeyay, si dadka isticmaala ay iska eegaan halkii ay weydiin lahaayeen.","also":["bogagga xaaladda","status page"]},{"id":"desk","g":"run","word":"Miiska adeegga","text":"Meesha ay yimaadaan su'aalaha iyo warbixinnada dadka isticmaala adeeggaaga. AI-gile mid kasta wuxuu u kala saaraa codsi, shil ama fikrad, wuxuuna sheegaa marka ay u egtahay wax hore loo soo sheegay.","also":["desk","miiska caawimada","helpdesk","service desk"]},{"id":"svcrequest","g":"run","word":"Codsi adeeg","text":"Marka qof codsado wax caadi ah, sida akoon cusub ama caawimo yar, halkii uu ka sheegi lahaa in wax jabeen. Wuxuu sugaa doorkiisa; shilku ayaa ka horreeya.","also":["codsiyada adeegga","codsi","service request"]},{"id":"incident","g":"run","word":"Shil","text":"Wax hadda u jaban dadka isticmaala, sida website-ka oo dhacay. Kaar 🔥 shil ah wuxuu ka horreeyaa safka: in mar kale la shaqeysiiyo ayaa ugu horreysa.","also":["shilal","incident","dhacdo"]},{"id":"major","g":"run","word":"Shil weyn","text":"Shil weyn: dad badan ayaa saameeyay, ama lacag ama xog ayaa khatar ku jira. Hal badhan ayaa koox kasta ku dhejiya (koox wada shaqeysa), toosiya cidda xilka haysa, oo codsada war xaaladeed 30 daqiiqo kasta.","also":["shilal waaweyn","major incident","dhacdo weyn"]},{"id":"oncall","g":"run","word":"Xilka qaadid","text":"Inaad noqoto qofka jawaaba marka wax jabaan, xitaa habeenkii. Adeeg kasta wuxuu leeyahay xubin koox oo xilka haysa oo marka hore la toosiyo shilalkiisa.","also":["xilka haya","on call","on-call"]},{"id":"replyby","g":"run","word":"Waqtiga jawaabta","text":"Inta kaar sugi karo jawaabta koowaad, tusaale ahaan saacad shil ahaan. Kadib wuxuu helaa saacad casaan ah, si aan waxba si aamusnaan ah loo illaawin. Waxaa kale oo loo yaqaan bartilmaameedka jawaabta.","also":["waqtiyada jawaabta","bartilmaameedka jawaabta"]},{"id":"postmortem","g":"run","word":"Dib-u-eegis shil","text":"Dib u eegis gaaban kadib shil: waxa dhacay, waxa caawiyay iyo waxa la beddelayo, iyadoo aan qofna la eedeynin. Shil lama xiri karo la'aanteed. Inta badan waxaa loo yaqaan post-mortem.","also":["post-mortem","postmortem","dib-u-eegista shilka"]},{"id":"problem","g":"run","word":"Dhibaato","text":"Sababta qarsoon ee ka dambeysa hal shil ama ka badan. Kaar 🧩 dhibaato ah wuxuu isku keenaa shilalka soo noqnoqda, si sababta loo helo oo weligeed loo hagaajiyo.","also":["dhibaatooyin","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Sababta aasaasiga ah","text":"Sababta dhabta ah ee wax u jabeen, ma aha oo keliya waxa aad aragtay inay khaldameen. Hagaaji sababta aasaasiga ah, shilkuna wuu joojiyaa soo noqoshada.","also":["sababaha aasaasiga ah","root cause"]},{"id":"workaround","g":"run","word":"Xal ku meel gaar ah","text":"Hab lagu sii shaqeysiiyo waxyaabaha ilaa hagaajinta dhabta ahi diyaar noqoto, sida dib u kicinta wax marka uu xayirmo. Waxaa lagu qoraa kaarka dhibaatada si aan qofna u baahan inuu mar kale ogaado.","also":["xalal ku meel gaar ah","workaround"]},{"id":"knownerror","g":"run","word":"Khalad la yaqaan","text":"Dhibaato sababteeda la fahmay oo leh xal ku meel gaar ah, laakiin aan weli la hagaajin. 🧩 Khaladaadka la yaqaan ayaa liis gareeya, si qof walba u isticmaalo xalka ku meel gaarka ah halkii uu mar kale qodi lahaa.","also":["khaladaadka la yaqaan","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Tilmaamo tallaabo-tallaabo ah oo lagu hagaajiyo nooc dhibaato la yaqaan, si mar kasta isku si oo degdeg ah loo sameeyo. Kadib shil weyn kooxdu waxay kuu soo jeedin kartaa mid aad oggolaato.","also":["runbooks","tilmaamaha shaqada"]},{"id":"ci","g":"run","word":"Alaab habayn","text":"Hal shay oo adeeggaagu ku tiirsan yahay, sida server, domain, shahaado, fure ama shirkad wax bixisa. 🗂️ Alaabta habaynta waxay u taxdaa adeeg kasta, si aad u aragto waxa shil saameeyo iyo waxa u baahan cusboonaysiin ama kayd.","also":["alaabta habaynta","configuration item"]},{"id":"expiry","g":"run","word":"Taariikhda dhicitaanka","text":"AI-gile wuxuu ilaaliyaa taariikhaha sida goorta ay dhacayso shahaado ama domain. 30 maalmood ka hor taariikhdaas wuxuu sameeyaa hal kaar oo lagu cusboonaysiinayo, si aysan waxba si lama filaan ah u joojin shaqada.","also":["taariikhaha dhicitaanka","dhicitaan","expiry"]},{"id":"backup","g":"run","word":"Kayd","text":"Nuqul la keydiyay oo xogtaada hore ah, oo lagu noqon karo haddii wax lumaan ama waxyeeloobaan. AI-gile waxay maalin kasta samaysaa kayd sabuuradahaaga.","also":["kaydad","backup","nuqul kayd"]},{"id":"restore","g":"run","word":"Soo celin","text":"Xogta oo laga soo celiyo kayd. Kayd runtii wuxuu tirsadaa marka aad ogtahay in la soo celin karo, sidaa darteed waa mudan tahay in mar mar la tijaabiyo.","also":["soo celi","la soo celiyay","restore"]},{"id":"svcreview","g":"run","word":"Dib-u-eegista adeegga","text":"Dib u eegid hal bil oo adeeg ah: shilalka la furay iyo kuwa la hagaajiyay, sida degdegga ah ee dadku jawaab u heleen, waqtiga shaqeynta iyo token-ka la isticmaalay. Dib-u-eegista bilaha ayaa tan u muujisa adeeg kasta.","also":["dib-u-eegista bilaha","service review"]},{"id":"accessreview","g":"run","word":"Dib-u-eegista galitaanka","text":"In 90-kii maalmood kasta la hubiyo cidda weli geli karta: xiriirada wadaagga, doorarka saaxiibada iyo siraha la kaydiyay. Mid kasta waad sii haysaa ama waad ka saaraysaa, si aan galitaan hore u sii jirin.","also":["access review"]},{"id":"improvements","g":"run","word":"Liiska horumarinta","text":"Wax kasta oo kooxdu go'aansatay inay ku fiicnaato, hal meel: soo jeedinta dib-eegista, hawlaha dib-u-eegista iyo hagaajinta dhibaatooyinka, mid walbana xaaladdiisa. Ka hel 📈 Horumarinta.","also":["horumarinta","improvements"]},{"id":"tokencap","g":"run","word":"Xadka token-ka","text":"Xad bil kasta ah oo ku saabsan token-ka ay wakiilada adeeggu isticmaali karaan. 80% waxaad helaysaa digniin; 100% shaqadooda gadaasha ayaa sugaysa ilaa bisha xigta ama ilaa aad xadka kor u qaaddo.","also":["xadadka token-ka","token cap"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI naftiisa u shaqeeya hawl: wuxuu akhriyaa koodhka, wuxuu sameeyaa isbeddello, wuxuu socodsiiyaa hubin, wuuna soo sheegaa.","also":["agents"]},{"id":"token","g":"ai","word":"Token","text":"Cutubka lagu tiriyo isticmaalka AI: qiyaas dhawr xaraf oo qoraal ah oo la akhriyay ama la qoray. Token yar, qorshahaaga wax badan ayaa hadha.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Amar yar oo naftiisa u socda waqti go'an, tusaale marka kalfadhi AI bilaabmo, si kooxdu u maqasho faallooyinkaaga.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
